  useEffect(() => {
    const ids = Object.keys(activeTracks);
    storage.saveActiveTracks(ids);
    const volumes: Record<string, number> = {};
    for (const [id, s] of Object.entries(activeTracks)) {
      volumes[id] = (s as { volume: number }).volume;
